mapper.select:
/* selectSAA000 - Lee JiSeob */
SELECT INST_NO, RPRSV_NM_ENCPT, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT
FROM SAA000

mapper.update:

/* updateSAA000 - Lee JiSeob */

UPDATE SAA000

SET
    RPRSV_NM_ENCPT = #{RPRSV_NM_ENCPT},
    PIC_NM_ENCPT = #{PIC_NM_ENCPT},
    PIC_TELNO = #{PIC_TELNO},
    PIC_MBL_TELNO_ENCPT = #{PIC_MBL_TELNO_ENCPT}

WHERE
    INST_NO = #{INST_NO}

